import React, {useEffect, useMemo, useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity, ArrowDownRight, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Download, FileText, Filter, Home, LayoutDashboard, ListFilter, LockKeyhole, MapPin, Menu, MoreHorizontal, Plus, Search, Settings, Shield, Ticket, UploadCloud, UserRound, Users, Wifi, Wrench, X} from 'lucide-react';
import {customers, services, initialTickets, initialVouchers, regions} from './data';
import CompanyLanding from './Landing';
import {ResetPassword,FirstLogin,CustomerForm,ServiceForm,TechnicianProfile} from './ExtraPages';
import UsersPage from './UsersPage';
import VoucherPage from './VoucherPage';
import ImportExport from './ImportExport';
import {canTransition,transitionTicket,canCorrectVoucher} from './domain';
import './style.css';

const iconMap={dashboard:LayoutDashboard,customers:Users,services:Wifi,tickets:Ticket,map:MapPin,vouchers:FileText,data:UploadCloud,users:Shield,settings:Settings,profile:UserRound,help:CircleHelp};
const go=(path)=>{window.history.pushState({},'',path);window.dispatchEvent(new PopStateEvent('popstate'));window.scrollTo(0,0)};
const Link=({to,children,className='',onClick,...props})=><a href={to} className={className} onClick={e=>{e.preventDefault();onClick?.(e);go(to)}} {...props}>{children}</a>;
const Brand=({small=false})=><div className={'brand '+(small?'brand-small':'')}><img src="/logo-nat.png" alt="Logo PT Nirwana Akses Teknologi"/><span>Nirwana<span className="brand-sub">Management System</span></span></div>;
const Badge=({children,type})=><span className={'badge '+(type||String(children).toLowerCase().replaceAll(' ','-'))}>{children}</span>;
const Button=({children,variant='',onClick,type='button',disabled=false})=><button type={type} className={'btn '+variant} onClick={onClick} disabled={disabled}>{children}</button>;
const Header=({eyebrow,title,description,actions})=><div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{actions&&<div className="heading-actions">{actions}</div>}</div>;
const Panel=({title,action,children,className=''})=><section className={'panel '+className}><div className="panel-head"><h2>{title}</h2>{action}</div>{children}</section>;
const Metric=({label,value,note,icon:Icon=Activity,color=''})=><div className="metric"><div className={'metric-icon '+color}><Icon size={19}/></div><div className="metric-label">{label}</div><div className="metric-value">{value}</div>{note&&<div className="metric-note">{note}</div>}</div>;
const Empty=({title='Tidak ada data',description='Coba ubah pencarian atau filter Anda.',icon:Icon=Search})=><div className="empty"><Icon size={28}/><strong>{title}</strong><p>{description}</p></div>;
const Field=({label,children,hint})=><label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;
const Select=({value,onChange,options,placeholder})=><select value={value} onChange={e=>onChange(e.target.value)}>{placeholder&&<option value="">{placeholder}</option>}{options.map(o=><option key={o} value={o}>{o}</option>)}</select>;
const SearchBox=({value,onChange,placeholder='Cari data...'})=><label className="searchbox"><Search size={17}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>;
const Timeline=({events})=><div className="timeline">{events.map((event,i)=><div className="timeline-row" key={i}><div className="timeline-dot"/><div><strong>{event.title}</strong><small>{event.time} · {event.by}</small><p>{event.note}</p></div></div>)}</div>;
const Table=({columns,rows,onRow})=><div className="table-wrap"><div className="table-scroll"><table><thead><tr>{columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i} onClick={onRow?()=>onRow(i):undefined} className={onRow?'clickable':''}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div><div className="table-cards">{rows.map((row,i)=><div className={'table-card '+(onRow?'clickable':'')} key={i} onClick={onRow?()=>onRow(i):undefined}>{row.map((cell,j)=>columns[j]&&cell?<div key={j}><span>{columns[j]}</span><strong>{cell}</strong></div>:null)}</div>)}</div>{rows.length===0&&<Empty/>}</div>;
const Tabs=({items,value,onChange})=><div className="tabs">{items.map(item=><button key={item} className={value===item?'selected':''} onClick={()=>onChange(item)}>{item}</button>)}</div>;
const serviceOf=t=>services.find(s=>s.id===t.serviceId)||services[0];

function App(){
  const [path,setPath]=useState(location.pathname); const [tickets,setTickets]=useState(initialTickets); const [vouchers,setVouchers]=useState(initialVouchers); const [toast,setToast]=useState(''); const [modal,setModal]=useState(null); const [mobileMenu,setMobileMenu]=useState(false); const [updates,setUpdates]=useState({});
  useEffect(()=>{const fn=()=>{setPath(location.pathname);setMobileMenu(false)};window.addEventListener('popstate',fn);return()=>window.removeEventListener('popstate',fn)},[]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3500);return()=>clearTimeout(t)},[toast]);
  const role=path.split('/')[1]; const isOps=['admin','officer'].includes(role); const isClient=role==='client'; const isTech=role==='technician';
  const notify=s=>setToast(s); const addTicket=(input)=>{const id=Math.max(...tickets.map(t=>t.id))+1;const nextNumber=Math.max(...tickets.map(t=>Number(t.number.split('-').at(-1))))+1;const record={id,number:`TKT-2026-${String(nextNumber).padStart(3,'0')}`,title:input.title||'Gangguan layanan internet',customer:'Budi Santoso',serviceId:Number(input.serviceId),priority:'MEDIUM',status:'NEW',tech:'Belum ditugaskan',region:serviceOf({serviceId:Number(input.serviceId)}).region,created:'04 Okt 2026 · baru saja',updated:'Baru saja',description:input.description,history:[{title:'Laporan dibuat',time:'Baru saja',by:'Budi Santoso',note:input.description}]};setTickets([record,...tickets]);return record};
  const updateTicket=(id,data)=>{const current=tickets.find(t=>t.id===id);if(!current||current.archived){notify('Tiket arsip hanya dapat dibaca');return}if(data.status&&data.status!==current.status&&!canTransition(current,data.status)){notify('Perubahan status tidak sesuai alur tiket');return}setTickets(prev=>prev.map(t=>{if(t.id!==id)return t;const transitioned=data.status&&data.status!==t.status?transitionTicket(t,data.status,data.note||'Status diperbarui.',role==='technician'?'Andi Saputra':'Nadia · Officer'):t;return {...transitioned,...data,history:data.status&&data.status!==t.status?transitioned.history:[...t.history,{title:'Progress ditambahkan',time:'Baru saja',by:role==='technician'?'Andi Saputra':'Nadia · Officer',note:data.note||'Pembaruan tiket tersimpan.'}]}}));notify('Pembaruan tiket tersimpan')};
  const archiveTicket=id=>{setTickets(prev=>prev.map(t=>t.id===id&&t.status==='SELESAI'?{...t,archived:true}:t));notify('Tiket selesai diarsipkan')};
  const changeVoucher=(index,delta)=>{setVouchers(prev=>prev.map((v,i)=>i===index?{...v,count:Math.max(0,v.count+delta)}:v));notify('Saldo voucher diperbarui dalam simulasi')};
  let content;
  if(path==='/') content=<CompanyLanding Brand={Brand} Link={Link}/>;
  else if(path==='/login') content=<Login/>;
   else if(path==='/forgot-password') content=<Forgot notify={notify}/>;
   else if(path==='/reset-password') content=<ResetPassword go={go} notify={notify}/>;
   else if(path==='/first-login') content=<FirstLogin go={go} notify={notify}/>;
  else if(isClient) content=<ClientPages path={path} tickets={tickets} addTicket={addTicket} notify={notify}/>;
   else if(isOps) content=<OpsPages path={path} role={role} tickets={tickets} updateTicket={updateTicket} archiveTicket={archiveTicket} vouchers={vouchers} changeVoucher={changeVoucher} notify={notify} setModal={setModal}/>;
  else if(isTech) content=<TechPages path={path} tickets={tickets} updateTicket={updateTicket} vouchers={vouchers} changeVoucher={changeVoucher} notify={notify}/>;
  else content=<div className="notfound"><h1>Halaman tidak ditemukan</h1><Button onClick={()=>go('/')}>Kembali ke beranda</Button></div>;
  return <>{isOps?<OpsShell role={role} path={path} mobileMenu={mobileMenu} setMobileMenu={setMobileMenu}>{content}</OpsShell>:isClient?<ClientShell path={path} mobileMenu={mobileMenu} setMobileMenu={setMobileMenu}>{content}</ClientShell>:isTech?<TechShell path={path} mobileMenu={mobileMenu} setMobileMenu={setMobileMenu}>{content}</TechShell>:content}<RoleSwitcher role={role}/>{toast&&<div className="toast"><CheckCircle2 size={18}/>{toast}</div>}{modal&&<div className="modal-backdrop" onClick={()=>setModal(null)}><div className="modal" onClick={e=>e.stopPropagation()}><button className="icon-button modal-x" onClick={()=>setModal(null)} aria-label="Tutup"><X size={18}/></button><h2>{modal.title}</h2><p>{modal.body}</p><div className="modal-actions"><Button variant="soft" onClick={()=>setModal(null)}>Batal</Button><Button onClick={()=>{modal.action?.();setModal(null)}}>Konfirmasi</Button></div></div></div>}</>;
}

function RoleSwitcher({role}){const [open,setOpen]=useState(false);return <div className={'role-switcher '+(open?'open':'')}><button className="role-trigger" onClick={()=>setOpen(!open)}><span className="demo-dot"/> Mode demo <ChevronDown size={15}/></button>{open&&<div className="role-menu"><span>Lihat sebagai</span>{[['Website Publik','/'],['Client','/client/dashboard'],['Admin','/admin/dashboard'],['Officer','/officer/dashboard'],['Teknisi','/technician/dashboard']].map(([name,url])=><button key={name} onClick={()=>{go(url);setOpen(false)}}>{name}{role===url.split('/')[1]&&<Check size={15}/>}</button>)}</div>}</div>}
function ShellNav({role,path,items}){return <nav className="side-links">{items.map(([label,slug])=>{const Icon=iconMap[slug];const href=`/${role}/${slug==='profile'?'profile':slug}`;return <Link key={slug} to={href} className={path===href||path.startsWith(href+'/')?'active':''}><Icon size={18}/>{label}</Link>})}</nav>}
function OpsShell({role,path,mobileMenu,setMobileMenu,children}){const items=[['Dashboard','dashboard'],['Pelanggan','customers'],['Layanan','services'],['Tiket','tickets'],['Peta Layanan','map'],['Stok Voucher','vouchers'],['Import / Export','data']];return <div className="app-shell ops-shell"><aside className={'sidebar '+(mobileMenu?'show':'')}><Link to="/"><Brand/></Link><div className="sidebar-label">WORKSPACE</div><ShellNav role={role} path={path} items={items}/>{role==='admin'&&<><div className="sidebar-label administration">ADMINISTRATION</div><ShellNav role={role} path={path} items={[["Pengguna & Akses","users"],["Pengaturan","settings"]]}/></>}<div className="sidebar-foot"><div className="avatar">{role==='admin'?'NA':'NO'}</div><div><strong>{role==='admin'?'Nadia Amelia':'Nadia Officer'}</strong><small>{role==='admin'?'Administrator':'Officer Operasional'}</small></div><MoreHorizontal size={18}/></div></aside><div className="shell-main"><div className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMobileMenu(!mobileMenu)} aria-label="Buka menu"><Menu size={21}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/> <strong>{path.split('/')[2]?.replaceAll('-',' ')||'Dashboard'}</strong></div><div className="topbar-right"><span className="topbar-date">Minggu, 4 Oktober 2026</span><button className="icon-button" aria-label="Notifikasi"><Bell size={19}/><i/></button><div className="avatar small">NA</div></div></div><main className="main-content">{children}</main></div></div>}
function ClientShell({path,mobileMenu,setMobileMenu,children}){const links=[['Beranda','/client/dashboard',Home],['Layanan Saya','/client/services',Wifi],['Tiket Saya','/client/tickets',Ticket],['Profil','/client/profile',UserRound],['Bantuan','/client/help',CircleHelp]];return <div className="client-shell"><header className="client-top"><Link to="/client/dashboard"><Brand small/></Link><nav className={mobileMenu?'show':''}>{links.map(([label,url])=><Link key={url} to={url} className={path===url||path.startsWith(url+'/')?'active':''}>{label}</Link>)}</nav><div className="client-top-right"><span className="avatar">BS</span><span className="client-name">Budi Santoso</span><button className="icon-button mobile-menu" aria-label="Buka menu" onClick={()=>setMobileMenu(!mobileMenu)}><Menu size={21}/></button></div></header><main className="client-main">{children}</main><nav className="bottom-nav">{links.slice(0,4).map(([label,url,Icon])=><Link key={url} to={url} className={path===url||path.startsWith(url+'/')?'active':''}><Icon size={20}/><span>{label}</span></Link>)}</nav></div>}
function TechShell({path,mobileMenu,setMobileMenu,children}){const links=[['Dashboard','dashboard'],['Ticket','tickets'],['Peta','map'],['Voucher','vouchers'],['Profil','profile']];return <div className="app-shell tech-shell"><aside className={'sidebar '+(mobileMenu?'show':'')}><Link to="/"><Brand/></Link><div className="sidebar-label">FIELD WORKSPACE</div><ShellNav role="technician" path={path} items={links.map(([label,s])=>[label,s])}/><div className="sidebar-foot"><div className="avatar">AS</div><div><strong>Andi Saputra</strong><small>Teknisi Lapangan</small></div></div></aside><div className="shell-main"><div className="topbar"><button className="icon-button mobile-menu" aria-label="Buka menu" onClick={()=>setMobileMenu(!mobileMenu)}><Menu size={21}/></button><div className="breadcrumb">Workspace Teknisi <ChevronRight size={14}/> <strong>{path.split('/')[2]}</strong></div><div className="topbar-right"><Bell size={19}/><div className="avatar small">AS</div></div></div><main className="main-content tech-content">{children}</main></div><nav className="bottom-nav tech-bottom">{links.map(([label,s])=>{const Icon=iconMap[s];const url='/technician/'+s;return <Link key={s} to={url} className={path.startsWith(url)?'active':''}><Icon size={20}/><span>{label}</span></Link>})}</nav></div>}

function Login(){const [phone,setPhone]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');return <div className="auth"><div className="auth-brand"><Link to="/"><Brand/></Link><div><span className="auth-kicker">NIRWANA MANAGEMENT SYSTEM</span><h1>Satu ruang kerja.<br/>Semua layanan terhubung.</h1><p>Akses informasi layanan, kelola laporan gangguan, dan pantau setiap langkah penanganan dengan mudah.</p></div><span className="auth-bottom">PT Nirwana Akses Teknologi · Prototype 2026</span></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={e=>{e.preventDefault();if(!phone||!password){setError('Isi nomor telepon dan password untuk melanjutkan.');return}const next=new URLSearchParams(location.search).get('next');go(next?.startsWith('/client/')?next:'/client/dashboard')}}><div className="eyebrow">SELAMAT DATANG KEMBALI</div><h2>Masuk ke akun Anda</h2><p>Gunakan nomor telepon yang terdaftar untuk melanjutkan.</p><Field label="Nomor WhatsApp / Nomor Telepon"><input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Contoh: 0812 3456 7890" inputMode="tel"/></Field><Field label="Password"><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Masukkan password"/></Field>{error&&<div className="form-error">{error}</div>}<div className="align-right"><Link to="/forgot-password" className="text-link">Lupa password?</Link></div><Button type="submit" variant="full">Masuk <ArrowRight size={17}/></Button><div className="auth-hint">Prototype: isi sembarang nomor dan password. Gunakan <strong>Mode demo</strong> untuk mencoba peran lain.</div></form></div></div>}
function Forgot({notify}){const [step,setStep]=useState(0);const [phone,setPhone]=useState('');const [otp,setOtp]=useState('');const [pass,setPass]=useState('');const [error,setError]=useState('');return <div className="auth"><div className="auth-brand"><Link to="/"><Brand/></Link><div><span className="auth-kicker">PEMULIHAN AKUN</span><h1>Kembali terhubung<br/>dengan mudah.</h1><p>Pulihkan akses akun Anda melalui langkah verifikasi sederhana.</p></div><span className="auth-bottom">PT Nirwana Akses Teknologi · Prototype 2026</span></div><div className="auth-form-wrap"><form className="auth-form" onSubmit={e=>{e.preventDefault();setError('');if(step===0&&!phone){setError('Masukkan nomor WhatsApp.');return}if(step===1&&otp.length!==6){setError('Masukkan 6 digit kode verifikasi.');return}if(step===2&&pass.length<6){setError('Password minimal 6 karakter.');return}if(step===1){go('/reset-password');return}if(step===2){setStep(3);notify('Password berhasil diperbarui dalam simulasi')}else setStep(step+1)}}><Link className="back-link" to="/login"><ArrowLeft size={16}/> Kembali ke login</Link><div className="eyebrow">LANGKAH {Math.min(step+1,3)} DARI 3</div><h2>{['Lupa password?','Verifikasi nomor Anda','Buat password baru','Password diperbarui'][step]}</h2><p>{['Masukkan nomor WhatsApp yang terhubung dengan akun.','Kode verifikasi dikirim ke '+(phone||'+62 812••••1234')+'.','Gunakan password yang mudah Anda ingat.','Anda dapat kembali masuk dengan password baru.'][step]}</p>{step===0&&<Field label="Nomor WhatsApp"><input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="0812 3456 7890" inputMode="tel"/></Field>}{step===1&&<><Field label="Kode verifikasi 6 digit"><input className="otp-input" value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="••••••" inputMode="numeric" maxLength={6}/></Field><div className="otp-footer">Kode berlaku 04:32 <button type="button" onClick={()=>notify('Kode baru dikirim dalam simulasi')}>Kirim ulang kode</button></div></>}{step===2&&<Field label="Password baru"><input type="password" value={pass} onChange={e=>setPass(e.target.value)} placeholder="Minimal 6 karakter"/></Field>}{error&&<div className="form-error">{error}</div>}{step<3?<Button type="submit" variant="full">{['Kirim kode verifikasi','Verifikasi kode','Simpan password'][step]} <ArrowRight size={17}/></Button>:<Button variant="full" onClick={()=>go('/login')}>Kembali ke login</Button>}<div className="auth-hint">Alur OTP ini hanya simulasi visual. Tidak ada pesan yang benar-benar dikirim.</div></form></div></div>}

function ClientPages({path,tickets,addTicket,notify}){const [tab,setTab]=useState('Semua');const [serviceId,setServiceId]=useState(new URLSearchParams(location.search).get('service')||'1');const [category,setCategory]=useState('');const [description,setDescription]=useState('');const [error,setError]=useState('');const [createdTicket,setCreatedTicket]=useState(null);useEffect(()=>{if(path==='/client/tickets/create'){const selected=new URLSearchParams(location.search).get('service');if(selected)setServiceId(selected)}},[path]);const clientServices=services.filter(s=>s.owner==='Budi Santoso');const clientTickets=tickets.filter(t=>t.customer==='Budi Santoso');const selectedTicket=tickets.find(t=>t.id===Number(path.split('/')[3]))||tickets[0]; const selectedService=services.find(s=>s.id===Number(path.split('/')[3]))||services[0];
  if(path==='/client/dashboard')return <><Header eyebrow="PORTAL PELANGGAN" title="Halo, Budi 👋" description="Berikut informasi layanan dan laporan gangguan Anda." actions={<Button onClick={()=>go('/client/tickets/create')}><Plus size={17}/> Buat laporan</Button>}/><div className="metrics three"><Metric label="Layanan aktif" value="2" note="Di 2 lokasi berbeda" icon={Wifi} color="blue"/><Metric label="Tiket aktif" value={clientTickets.filter(t=>t.status!=='SELESAI').length} note="Sedang dalam penanganan" icon={Ticket} color="amber"/><Metric label="Tiket selesai" value="7" note="Riwayat penanganan" icon={CheckCircle2} color="green"/></div><div className="two-col"><Panel title="Layanan Saya" action={<Link className="text-link" to="/client/services">Lihat semua <ArrowRight size={15}/></Link>}><div className="service-list">{clientServices.map(s=><ServiceCard key={s.id} service={s}/>)}</div></Panel><Panel title="Tiket Aktif" action={<Link className="text-link" to="/client/tickets">Lihat semua <ArrowRight size={15}/></Link>}><div className="ticket-list">{clientTickets.filter(t=>t.status!=='SELESAI').map(t=><TicketCard key={t.id} ticket={t} link={'/client/tickets/'+t.id}/>)}</div></Panel></div></>;
  if(path==='/client/services')return <><Header eyebrow="AKUN SAYA" title="Layanan Saya" description="Setiap layanan dan lokasi pemasangan yang terhubung dengan akun Anda."/><div className="cards-grid">{clientServices.map(s=><ServiceCard key={s.id} service={s} full/>)}</div></>;
  if(path.startsWith('/client/services/'))return <><Link className="back-link" to="/client/services"><ArrowLeft size={16}/> Semua layanan</Link><Header eyebrow="DETAIL LAYANAN" title={selectedService.name} description={selectedService.number} actions={<Button onClick={()=>go('/client/tickets/create?service='+selectedService.id)}><Plus size={17}/> Laporkan gangguan</Button>}/><div className="two-col detail-grid"><Panel title="Informasi layanan"><Details items={[["Nomor layanan",selectedService.number],["Status",<Badge>{selectedService.status}</Badge>],["Paket",selectedService.package],["Wilayah",selectedService.region],["Alamat pemasangan",selectedService.address],["Tanggal pemasangan",selectedService.installed]]}/></Panel><Panel title="Riwayat gangguan">{clientTickets.filter(t=>t.serviceId===selectedService.id).map(t=><TicketCard key={t.id} ticket={t} link={'/client/tickets/'+t.id}/>)}{!clientTickets.some(t=>t.serviceId===selectedService.id)&&<Empty title="Belum ada laporan gangguan"/>}</Panel></div></>;
  if(path==='/client/tickets/create')return createdTicket?<div className="success-state panel"><div className="success-icon"><CheckCircle2 size={31}/></div><div className="eyebrow">LAPORAN TERCATAT</div><h1>Laporan berhasil dibuat</h1><p>Tim kami akan meninjau gangguan pada {serviceOf(createdTicket).name}. Pantau progress melalui halaman tiket.</p><div className="success-number">#{createdTicket.number}</div><Button onClick={()=>{go('/client/tickets/'+createdTicket.id);setCreatedTicket(null)}}>Lihat tiket <ArrowRight size={17}/></Button></div>:<div className="narrow-page"><Link className="back-link" to="/client/tickets"><ArrowLeft size={16}/> Tiket Saya</Link><Header eyebrow="LAPORAN GANGGUAN" title="Laporkan gangguan" description="Ceritakan kendala pada layanan Anda. Tim kami akan membantu menanganinya."/><form className="panel form-panel" onSubmit={e=>{e.preventDefault();if(!description.trim()){setError('Tuliskan deskripsi gangguan terlebih dahulu.');return}setCreatedTicket(addTicket({serviceId,title:category||'Gangguan layanan internet',description:description.trim()}))}}><Field label="Layanan yang bermasalah"><select value={serviceId} onChange={e=>setServiceId(e.target.value)}>{clientServices.map(s=><option value={s.id} key={s.id}>{s.name} · {s.number} · {s.region}</option>)}</select></Field><Field label="Kategori masalah (opsional)"><Select value={category} onChange={setCategory} placeholder="Pilih kategori" options={['Internet tidak dapat digunakan','Koneksi lambat','Koneksi tidak stabil','Lainnya']}/></Field><Field label="Ceritakan gangguan Anda"><textarea value={description} onChange={e=>setDescription(e.target.value)} rows={5} placeholder="Contoh: Sejak pagi koneksi internet di rumah tidak dapat digunakan..."/></Field><Field label="Foto pendukung (opsional)"><input type="file" accept="image/*" className="file-input"/></Field>{error&&<div className="form-error">{error}</div>}<div className="form-actions"><span>Laporan akan terhubung ke layanan yang dipilih.</span><Button type="submit">Kirim laporan <ArrowRight size={17}/></Button></div></form></div>;
  if(path==='/client/tickets')return <><Header eyebrow="AKUN SAYA" title="Tiket Saya" description="Pantau laporan gangguan dan riwayat penanganannya." actions={<Button onClick={()=>go('/client/tickets/create')}><Plus size={17}/> Buat laporan</Button>}/><Panel><Tabs items={['Semua','Aktif','Selesai']} value={tab} onChange={setTab}/><div className="ticket-list spaced">{clientTickets.filter(t=>tab==='Semua'||(tab==='Aktif'?t.status!=='SELESAI':t.status==='SELESAI')).map(t=><TicketCard key={t.id} ticket={t} link={'/client/tickets/'+t.id}/>)}</div></Panel></>;
  if(path.startsWith('/client/tickets/'))return <><Link className="back-link" to="/client/tickets"><ArrowLeft size={16}/> Tiket Saya</Link><Header eyebrow={selectedTicket.number} title={selectedTicket.title} description={'Dilaporkan '+selectedTicket.created} actions={<Badge>{selectedTicket.status}</Badge>}/><div className="two-col detail-grid"><Panel title="Progress penanganan"><Timeline events={selectedTicket.history}/></Panel><div className="stack"><Panel title="Informasi laporan"><Details items={[["Layanan",serviceOf(selectedTicket).number],["Lokasi",serviceOf(selectedTicket).address],["Tanggal laporan",selectedTicket.created],["Status",<Badge>{selectedTicket.status}</Badge>]]}/></Panel><Panel title="Deskripsi gangguan"><p className="body-copy">{selectedTicket.description}</p></Panel></div></div></>;
  if(path==='/client/profile')return <><Header eyebrow="AKUN SAYA" title="Profil Saya" description="Informasi akun dan kontak Anda."/><div className="two-col detail-grid"><Panel title="Data pelanggan"><Details items={[["Nama lengkap","Budi Santoso"],["Nomor telepon","0812 •••• 1234"],["Status akun",<Badge>Aktif</Badge>],["Terdaftar sejak","12 Januari 2024"]]}/></Panel><Panel title="Keamanan akun"><p className="body-copy">Perbarui password secara berkala untuk menjaga keamanan akun Anda.</p><Button variant="soft" onClick={()=>go('/forgot-password')}><LockKeyhole size={16}/> Ubah password</Button></Panel></div></>;
  if(path==='/client/help')return <><Header eyebrow="BANTUAN" title="Ada yang bisa kami bantu?" description="Untuk gangguan layanan, buat laporan agar tim kami dapat menindaklanjutinya."/><Panel title="Bantuan pelanggan"><p className="body-copy">Pilih layanan yang bermasalah, jelaskan kendalanya, lalu pantau progress melalui Tiket Saya.</p><Button onClick={()=>go('/client/tickets/create')}>Buat laporan gangguan</Button></Panel></>;
  return <Empty title="Halaman tidak ditemukan"/>;
}
function Details({items}){return <dl className="details">{items.map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>}
function ServiceCard({service,full}){return <div className={'service-card '+(full?'full':'')}><div className="service-card-top"><div className="service-icon"><Wifi size={22}/></div><Badge>{service.status}</Badge></div><h3>{service.name}</h3><span className="id-text">{service.number}</span><div className="service-data"><span>Paket</span><strong>{service.package}</strong><span>Lokasi</span><strong>{service.region}</strong></div>{full&&<p className="address"><MapPin size={15}/>{service.address}</p>}<div className="service-actions"><Link className="text-link" to={'/client/services/'+service.id}>Lihat detail <ArrowRight size={15}/></Link><Link className="text-link secondary" to={'/client/tickets/create?service='+service.id}>Laporkan gangguan</Link></div></div>}
function TicketCard({ticket,link}){return <Link to={link} className="ticket-card"><div><div className="ticket-card-meta"><span className="id-text">#{ticket.number}</span><Badge>{ticket.status}</Badge></div><strong>{ticket.title}</strong><small>{serviceOf(ticket).name} · {serviceOf(ticket).region}</small></div><div className="ticket-card-end"><span>{ticket.updated}</span><ChevronRight size={19}/></div></Link>}

function OpsPages({path,role,tickets,updateTicket,archiveTicket,vouchers,changeVoucher,notify,setModal}){const section=path.split('/')[2], detail=path.split('/')[3];const base='/'+role;const [query,setQuery]=useState('');const [status,setStatus]=useState('Semua status');const [region,setRegion]=useState('Semua wilayah');const [priority,setPriority]=useState('Semua prioritas');const [technician,setTechnician]=useState('Semua teknisi');const [assignment,setAssignment]=useState('Semua penugasan');const [dateFilter,setDateFilter]=useState('Semua tanggal');const [packageFilter,setPackageFilter]=useState('Semua paket');const [tab,setTab]=useState('Overview');const [assigned,setAssigned]=useState('Andi Saputra');const [progressStatus,setProgressStatus]=useState('IN PROGRESS');const [note,setNote]=useState('');const [importStep,setImportStep]=useState(0);const [importTab,setImportTab]=useState('Import');const [file,setFile]=useState(null);const [mapSelected,setMapSelected]=useState(services[0]);const [mapError,setMapError]=useState(false);
  const filteredTickets=tickets.filter(t=>(t.number+' '+t.title+' '+t.customer+' '+serviceOf(t).number).toLowerCase().includes(query.toLowerCase())&&(status==='Semua status'||t.status===status)&&(priority==='Semua prioritas'||t.priority===priority)&&(region==='Semua wilayah'||t.region===region)&&(technician==='Semua teknisi'||t.tech===technician)&&(assignment==='Semua penugasan'||(assignment==='Belum ditugaskan'?t.tech==='Belum ditugaskan':t.tech!=='Belum ditugaskan'))&&(dateFilter==='Semua tanggal'||(dateFilter==='Hari ini'?t.created.startsWith('04 Okt'):!t.created.startsWith('04 Okt'))));
  const filteredCustomers=customers.filter(c=>(c.name+' '+c.phone).toLowerCase().includes(query.toLowerCase())&&(status==='Semua status'||c.status===status)&&(region==='Semua wilayah'||c.region===region));
  const filteredServices=services.filter(s=>(s.number+' '+s.owner+' '+s.package).toLowerCase().includes(query.toLowerCase())&&(status==='Semua status'||s.status===status)&&(region==='Semua wilayah'||s.region===region)&&(packageFilter==='Semua paket'||s.package===packageFilter));
  if(section==='customers'&&detail==='new')return <CustomerForm role={role} go={go} notify={notify}/>;
  if(section==='services'&&detail==='new')return <ServiceForm role={role} go={go} notify={notify}/>;
  if(section==='dashboard')return <><Header eyebrow={role==='admin'?'ADMIN WORKSPACE':'OFFICER WORKSPACE'} title="Dashboard Operasional" description="Ringkasan kondisi layanan dan penanganan gangguan hari ini."/><div className="filter-bar"><Select value={region} onChange={setRegion} options={regions}/><Select value={dateFilter} onChange={setDateFilter} options={['Semua tanggal','Hari ini','Sebelumnya']}/><Select value={technician} onChange={setTechnician} options={['Semua teknisi','Andi Saputra','Reza Putra','Belum ditugaskan']}/></div><div className="metrics five"><Metric label="Total pelanggan" value={customers.filter(c=>region==='Semua wilayah'||c.region===region).length} note="+42 bulan ini" icon={Users} color="blue"/><Metric label="Layanan aktif" value={services.filter(s=>s.status==='Aktif'&&(region==='Semua wilayah'||s.region===region)).length} note="92,6% dari layanan" icon={Wifi} color="green"/><Metric label="Tiket aktif" value={filteredTickets.filter(t=>t.status!=='SELESAI').length} note="Perlu dipantau" icon={Ticket} color="amber"/><Metric label="Belum ditugaskan" value={filteredTickets.filter(t=>t.tech==='Belum ditugaskan').length} note="Butuh tindakan" icon={Clock3} color="red"/><Metric label="Selesai" value={filteredTickets.filter(t=>t.status==='SELESAI').length} note="Dalam data demo" icon={CheckCircle2} color="purple"/></div><div className="two-col chart-grid"><Panel title="Tren laporan gangguan" action={<span className="muted">7 hari terakhir</span>}><div className="chart"><div className="chart-y"><span>40</span><span>30</span><span>20</span><span>10</span><span>0</span></div><div className="chart-bars">{[24,31,19,36,27,33,22].map((h,i)=><div key={i}><div className="bar" style={{height:(h/40*100)+'%'}}/><span>{['Sen','Sel','Rab','Kam','Jum','Sab','Min'][i]}</span></div>)}</div></div></Panel><Panel title="Distribusi status tiket"><div className="donut-wrap"><div className="donut"><div><strong>168</strong><span>Total tiket</span></div></div><div className="legend">{[['Baru','16','legend-blue'],['Dibuka','24','legend-cyan'],['Ditangani','32','legend-amber'],['Pending','12','legend-orange'],['Selesai','84','legend-green']].map(([l,v,c])=><div key={l}><i className={c}/><span>{l}</span><strong>{v}</strong></div>)}</div></div></Panel></div><Panel title="Tiket membutuhkan perhatian" action={<Link className="text-link" to={base+'/tickets'}>Lihat semua <ArrowRight size={15}/></Link>}><Table columns={['ID','Masalah','Pelanggan','Layanan','Prioritas','Status','Teknisi','Waktu']} rows={filteredTickets.filter(t=>t.status!=='SELESAI').map(t=>[<strong>#{t.number}</strong>,t.title,t.customer,serviceOf(t).number,<Badge>{t.priority}</Badge>,<Badge>{t.status}</Badge>,t.tech,t.updated])} onRow={i=>go(base+'/tickets/'+filteredTickets.filter(t=>t.status!=='SELESAI')[i].id)}/></Panel><Panel title="Aktivitas terbaru"><div className="activity-list"><span><i className="blue-dot"/> Tiket #TKT-2026-014 diperbarui oleh Andi Saputra <small>10 menit lalu</small></span><span><i className="orange-dot"/> Tiket #TKT-2026-015 menunggu penugasan <small>15 menit lalu</small></span><span><i className="green-dot"/> Tiket #TKT-2026-012 selesai ditangani <small>2 hari lalu</small></span></div></Panel></>;
  if(section==='customers'&&detail){const c=customers.find(x=>x.id===Number(detail))||customers[0];return <><Link className="back-link" to={base+'/customers'}><ArrowLeft size={16}/> Pelanggan</Link><Header eyebrow="DETAIL PELANGGAN" title={c.name} description={'Terdaftar sejak '+c.joined} actions={<Badge>{c.status}</Badge>}/><Panel><Tabs items={['Overview','Layanan','Tiket','Riwayat']} value={tab} onChange={setTab}/>{tab==='Overview'?<div className="two-col inner-grid"><Details items={[["Nama lengkap",c.name],["Nomor telepon",c.phone],["Wilayah",c.region],["Tanggal registrasi",c.joined],["Status akun",<Badge>{c.status}</Badge>]]}/><div className="info-callout"><Shield size={22}/><strong>Dokumen identitas</strong><p>Placeholder dokumen. Tidak menggunakan data pribadi nyata.</p></div></div>:tab==='Layanan'?<div className="service-list">{services.filter(s=>s.owner===c.name).map(s=><div className="mini-row" key={s.id}><Wifi size={18}/><div><strong>{s.name}</strong><small>{s.number} · {s.region}</small></div><Badge>{s.status}</Badge><Link to={base+'/services/'+s.id}><ArrowRight size={17}/></Link></div>)}</div>:tab==='Tiket'?<div className="ticket-list">{tickets.filter(t=>t.customer===c.name).map(t=><TicketCard key={t.id} ticket={t} link={base+'/tickets/'+t.id}/>)}</div>:<Empty title="Belum ada perubahan profil" description="Riwayat perubahan pelanggan akan terlihat di sini."/>}</Panel></>}
  if(section==='customers')return <><Header eyebrow="DATA OPERASIONAL" title="Pelanggan" description="Kelola data pelanggan dan layanan yang terhubung." actions={<Button onClick={()=>go(base+'/customers/new')}><Plus size={17}/> Tambah pelanggan</Button>}/><Panel><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Cari nama atau nomor telepon"/><Select value={status} onChange={setStatus} options={['Semua status','Aktif','Nonaktif']}/><Select value={region} onChange={setRegion} options={regions}/></div><Table columns={['Nama pelanggan','Nomor telepon','Jumlah layanan','Status akun','Registrasi','']} rows={filteredCustomers.map(c=>[<strong>{c.name}</strong>,c.phone,c.services,<Badge>{c.status}</Badge>,c.joined,<ChevronRight size={17}/>])} onRow={i=>go(base+'/customers/'+filteredCustomers[i].id)}/></Panel></>;
  if(section==='services'&&detail){const s=services.find(x=>x.id===Number(detail))||services[0];return <><Link className="back-link" to={base+'/services'}><ArrowLeft size={16}/> Layanan</Link><Header eyebrow="DETAIL LAYANAN" title={s.number} description={s.name} actions={<Badge>{s.status}</Badge>}/><div className="two-col detail-grid"><Panel title="Informasi layanan"><Details items={[["Pemilik",s.owner],["Paket",s.package],["Status layanan",<Badge>{s.status}</Badge>],["Wilayah",s.region],["Alamat",s.address],["Koordinat",s.coord],["Tanggal pemasangan",s.installed],["Catatan","Layanan pelanggan aktif dalam simulasi."]]}/><Button variant="soft" onClick={()=>go(base+'/map')}><MapPin size={16}/> Lihat di peta</Button></Panel><Panel title="Riwayat tiket">{tickets.filter(t=>t.serviceId===s.id).map(t=><TicketCard key={t.id} ticket={t} link={base+'/tickets/'+t.id}/>)}{!tickets.some(t=>t.serviceId===s.id)&&<Empty title="Belum ada tiket"/>}</Panel></div></>}
  if(section==='services')return <><Header eyebrow="DATA OPERASIONAL" title="Layanan" description="Setiap layanan memiliki lokasi, status, dan riwayat tiketnya sendiri." actions={<Button onClick={()=>go(base+'/services/new')}><Plus size={17}/> Tambah layanan</Button>}/><Panel><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Cari nomor layanan atau pelanggan"/><Select value={status} onChange={setStatus} options={['Semua status','Aktif','Nonaktif']}/><Select value={region} onChange={setRegion} options={regions}/><Select value={packageFilter} onChange={setPackageFilter} options={['Semua paket',...new Set(services.map(s=>s.package))]}/></div><Table columns={['Nomor layanan','Pelanggan','Paket','Wilayah','Status layanan','Pemasangan','']} rows={filteredServices.map(s=>[<strong>{s.number}</strong>,s.owner,s.package,s.region,<Badge>{s.status}</Badge>,s.installed,<ChevronRight size={17}/>])} onRow={i=>go(base+'/services/'+filteredServices[i].id)}/></Panel></>;
  if(section==='tickets'&&detail){const t=tickets.find(x=>x.id===Number(detail))||tickets[0];const s=serviceOf(t);const allowed=[t.status,...['OPEN','IN PROGRESS','PENDING','SELESAI'].filter(next=>canTransition(t,next))];const selectedProgress=allowed.includes(progressStatus)?progressStatus:allowed[0]||t.status;return <><Link className="back-link" to={base+'/tickets'}><ArrowLeft size={16}/> Ticket Gangguan</Link><Header eyebrow={'#'+t.number} title={t.title} description={'Dibuat '+t.created} actions={<><Badge>{t.priority}</Badge><Badge>{t.status}</Badge></>}/><div className="detail-actions">{t.archived&&<Badge>ARSIP · BACA SAJA</Badge>}{!t.archived&&t.status==='NEW'&&<Button onClick={()=>updateTicket(t.id,{status:'OPEN',note:'Tiket diterima.'})}>Terima / buka tiket</Button>}{!t.archived&&t.status==='SELESAI'&&<Button onClick={()=>updateTicket(t.id,{status:'OPEN',note:'Tiket dibuka kembali.'})}>Buka kembali</Button>}{!t.archived&&t.status==='IN PROGRESS'&&<Button onClick={()=>updateTicket(t.id,{status:'SELESAI',note:'Penanganan selesai.'})}>Tandai selesai</Button>}{role==='admin'&&!t.archived&&t.status==='SELESAI'&&<Button variant="soft" onClick={()=>setModal({title:'Arsipkan tiket?',body:'Tiket yang diarsipkan menjadi hanya baca.',action:()=>archiveTicket(t.id)})}>Arsipkan</Button>}<Button variant="soft" disabled={t.archived} onClick={()=>setModal({title:'Tugaskan teknisi',body:'Tugaskan Andi Saputra untuk menangani tiket ini?',action:()=>updateTicket(t.id,{tech:'Andi Saputra',note:'Andi Saputra ditugaskan.'})})}><Users size={16}/> Assign Teknisi</Button><Button variant="soft" disabled={t.archived} onClick={()=>document.getElementById('progress-form')?.scrollIntoView({behavior:'smooth'})}><Activity size={16}/> Ubah status / tambah progress</Button></div><div className="ticket-detail-grid"><div className="stack"><Panel title="Detail laporan"><Details items={[["Deskripsi masalah",t.description],["Tanggal laporan",t.created],["Foto laporan","Belum ada foto terlampir"]]}/></Panel><Panel title="Timeline & progress"><Timeline events={t.history}/></Panel><Panel title="Tambah progress" className="progress-panel"><form id="progress-form" onSubmit={e=>{e.preventDefault();if(!note.trim()){notify('Isi catatan progress terlebih dahulu');return}updateTicket(t.id,{status:selectedProgress,note:note.trim()});setNote('')}}><div className="form-row"><Field label="Status"><Select value={selectedProgress} onChange={setProgressStatus} options={allowed}/></Field><Field label="Foto progress (opsional)"><input type="file" accept="image/*"/></Field></div><Field label="Catatan tindakan"><textarea rows="4" value={note} onChange={e=>setNote(e.target.value)} placeholder="Tulis tindakan atau hasil pemeriksaan..."/></Field><Button type="submit" disabled={t.archived}>Simpan progress</Button></form></Panel></div><div className="stack"><Panel title="Pelanggan"><div className="side-entity"><div className="avatar">{t.customer.split(' ').map(x=>x[0]).join('')}</div><div><strong>{t.customer}</strong><span>0812 •••• 1234</span></div></div><Link className="text-link" to={base+'/customers/'+(customers.find(c=>c.name===t.customer)?.id||1)}>Lihat pelanggan <ArrowRight size={15}/></Link></Panel><Panel title="Layanan & lokasi"><Details items={[["Nomor layanan",s.number],["Paket",s.package],["Alamat",s.address],["Wilayah",s.region],["Status layanan",<Badge>{s.status}</Badge>]]}/></Panel><Panel title="Teknisi"><div className="side-entity"><div className="avatar">AS</div><div><strong>{t.tech}</strong><span>{t.tech==='Belum ditugaskan'?'Menunggu penugasan':'Teknisi utama'}</span></div></div>{t.tech!=='Belum ditugaskan'&&<div className="side-entity"><div className="avatar muted-avatar">RP</div><div><strong>Reza Putra</strong><span>Teknisi pendamping</span></div></div>}<Button variant="soft" onClick={()=>setModal({title:'Kelola teknisi',body:'Tambahkan Reza Putra sebagai teknisi pendamping?',action:()=>notify('Teknisi pendamping ditambahkan dalam simulasi')})}>Kelola teknisi</Button></Panel><Panel title="Waktu penanganan"><Details items={[["Response time","14 menit"],["Handling time","2 jam 18 menit"]]}/></Panel></div></div></>}
  if(section==='tickets')return <><Header eyebrow="OPERASIONAL" title="Ticket Gangguan" description="Pantau, prioritaskan, dan tindak lanjuti setiap laporan."/><div className="metrics four compact"><Metric label="New" value={tickets.filter(t=>t.status==='NEW').length+7} icon={Ticket} color="blue"/><Metric label="Open" value="12" icon={Clock3} color="purple"/><Metric label="In Progress" value="32" icon={Activity} color="amber"/><Metric label="Pending" value="8" icon={Filter} color="red"/></div><Panel><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Cari ID, pelanggan, layanan..."/><Select value={status} onChange={setStatus} options={['Semua status','NEW','OPEN','IN PROGRESS','PENDING','SELESAI']}/><Select value={priority} onChange={setPriority} options={['Semua prioritas','LOW','MEDIUM','HIGH','CRITICAL']}/><Select value={region} onChange={setRegion} options={regions}/><Select value={technician} onChange={setTechnician} options={['Semua teknisi','Andi Saputra','Reza Putra','Belum ditugaskan']}/><Select value={assignment} onChange={setAssignment} options={['Semua penugasan','Ditugaskan','Belum ditugaskan']}/><Select value={dateFilter} onChange={setDateFilter} options={['Semua tanggal','Hari ini','Sebelumnya']}/></div><Table columns={['Ticket ID','Pelanggan','Layanan','Masalah','Prioritas','Status','Teknisi','Dibuat','Update']} rows={filteredTickets.map(t=>[<strong>#{t.number}</strong>,t.customer,serviceOf(t).number,t.title,<Badge>{t.priority}</Badge>,<Badge>{t.status}</Badge>,t.tech,t.created.split(' · ')[0],t.updated])} onRow={i=>go(base+'/tickets/'+filteredTickets[i].id)}/></Panel></>;
  if(section==='map')return <><Header eyebrow="LOKASI LAYANAN" title="Peta Layanan" description="Lokasi pemasangan berdasarkan koordinat layanan."/><div className="filter-bar"><SearchBox value={query} onChange={setQuery} placeholder="Cari pelanggan atau layanan"/><Select value={region} onChange={setRegion} options={regions}/><Select value={status} onChange={setStatus} options={['Semua status','Aktif','Nonaktif']}/><Button variant="soft" onClick={()=>setMapError(!mapError)}>{mapError?'Tampilkan peta':'Simulasikan gagal peta'}</Button></div><div className="map-layout"><div className="panel map-panel">{mapError?<Empty icon={MapPin} title="Map tidak dapat dimuat" description="Daftar layanan di samping tetap tersedia. Coba kembali nanti."/>:<div className="map-canvas"><div className="map-road road-a"/><div className="map-road road-b"/><div className="map-road road-c"/><div className="map-road road-d"/><div className="map-label label-a">BANDUNG UTARA</div><div className="map-label label-b">BANDUNG TIMUR</div><div className="map-label label-c">BANDUNG SELATAN</div>{services.filter(s=>s.coord!=='—').map((s,i)=><button key={s.id} className={'map-marker marker-'+i+(mapSelected.id===s.id?' selected':'')} onClick={()=>setMapSelected(s)} aria-label={'Lihat '+s.number}><MapPin size={27} fill="currentColor"/></button>)}<div className="map-popup"><strong>{mapSelected.owner}</strong><span>{mapSelected.number} · {mapSelected.status}</span><small>{mapSelected.address}</small><Link className="text-link" to={base+'/services/'+mapSelected.id}>Detail layanan <ArrowRight size={14}/></Link></div></div>}</div><Panel title="Daftar layanan"><div className="map-service-list">{services.filter(s=>(s.owner+' '+s.number).toLowerCase().includes(query.toLowerCase())&&(region==='Semua wilayah'||s.region===region)&&(status==='Semua status'||s.status===status)).map(s=><button key={s.id} onClick={()=>setMapSelected(s)} className={mapSelected.id===s.id?'selected':''}><MapPin size={17}/><span><strong>{s.number}</strong><small>{s.owner} · {s.region}</small></span><Badge>{s.status}</Badge></button>)}</div><div className="map-incomplete"><strong>Lokasi belum lengkap</strong><p>1 layanan tanpa koordinat: SRV-2026-004</p></div></Panel></div></>;
  if(section==='vouchers')return <VoucherPage role={role} vouchers={vouchers} changeVoucher={changeVoucher} notify={notify}/>;
  if(section==='data')return <ImportExport notify={notify}/>;
  if(section==='users'&&role==='admin')return <UsersPage notify={notify}/>;
  if(section==='settings'&&role==='admin')return <><Header eyebrow="ADMINISTRATION" title="Pengaturan" description="Gambaran konfigurasi portal Nirwana."/><Panel title="Informasi perusahaan"><Details items={[["Nama","PT Nirwana Akses Teknologi"],["Nama sistem","Nirwana Management System"],["Zona waktu","WIB (UTC+7)"],["Mode","Prototype UI/UX"]]}/></Panel></>;
  return <Empty title="Halaman tidak ditemukan"/>;
}
function TechPages({path,tickets,updateTicket,vouchers,changeVoucher,notify}){const section=path.split('/')[2],detail=path.split('/')[3];const [status,setStatus]=useState('IN PROGRESS');const [note,setNote]=useState('');const myTickets=tickets.filter(t=>t.tech==='Andi Saputra');const unassigned=tickets.filter(t=>t.tech==='Belum ditugaskan');const t=tickets.find(x=>x.id===Number(detail))||tickets[0];if(section==='dashboard')return <><Header eyebrow="WORKSPACE TEKNISI" title="Selamat pagi, Andi 👋" description="Berikut pekerjaan yang perlu Anda tangani hari ini."/><div className="metrics four"><Metric label="Pekerjaan saya" value="5" icon={Ticket} color="blue"/><Metric label="Perlu dikerjakan" value="3" icon={Clock3} color="amber"/><Metric label="Pending" value="1" icon={Filter} color="red"/><Metric label="Selesai hari ini" value="4" icon={CheckCircle2} color="green"/></div><Panel title="Pekerjaan Saya" action={<Link className="text-link" to="/technician/tickets">Lihat semua <ArrowRight size={15}/></Link>}><div className="tech-card-grid">{myTickets.map(t=><TechCard key={t.id} ticket={t}/>)}</div></Panel><Panel title="Tiket belum ditugaskan"><div className="tech-card-grid">{unassigned.map(t=><div className="tech-task" key={t.id}><div className="tech-task-top"><Badge>{t.priority}</Badge><span>#{t.number}</span></div><h3>{t.title}</h3><p>{t.customer} · {serviceOf(t).region}</p><Button variant="soft" onClick={()=>{updateTicket(t.id,{tech:'Andi Saputra',status:'OPEN',note:'Tiket diklaim oleh Andi Saputra.'});notify('Tiket diklaim dalam simulasi')}}>Klaim tiket</Button></div>)}</div></Panel></>;
if(section==='tickets'&&detail){const allowed=[t.status,...['OPEN','IN PROGRESS','PENDING','SELESAI'].filter(next=>canTransition(t,next))];const selectedStatus=allowed.includes(status)?status:allowed[0]||t.status;return <><Link className="back-link" to="/technician/tickets"><ArrowLeft size={16}/> Semua tiket</Link><Header eyebrow={'#'+t.number} title={t.title} description={'Dilaporkan '+t.created} actions={<Badge>{t.priority}</Badge>}/><div className="detail-actions">{!t.archived&&t.status==='NEW'&&<Button onClick={()=>updateTicket(t.id,{status:'OPEN',note:'Tiket diterima teknisi.'})}>Terima tiket</Button>}{!t.archived&&t.status==='OPEN'&&<Button onClick={()=>updateTicket(t.id,{status:'IN PROGRESS',note:'Pekerjaan dimulai.'})}>Mulai pekerjaan</Button>}{!t.archived&&t.status==='IN PROGRESS'&&<Button variant="soft" onClick={()=>updateTicket(t.id,{status:'PENDING',note:'Menunggu tindak lanjut.'})}>Pending</Button>}{!t.archived&&['IN PROGRESS','PENDING'].includes(t.status)&&<Button onClick={()=>updateTicket(t.id,{status:'SELESAI',note:'Pekerjaan selesai.'})}>Selesai</Button>}{t.archived&&<Badge>ARSIP · BACA SAJA</Badge>}</div><div className="tech-detail-layout"><div className="stack"><Panel title="Informasi pekerjaan"><Details items={[["Pelanggan",t.customer],["Layanan",serviceOf(t).number],["Lokasi",serviceOf(t).address],["Status",<Badge>{t.status}</Badge>],["Teknisi lain","Reza Putra"]]}/><Button variant="soft" onClick={()=>go('/technician/map')}><MapPin size={16}/> Buka peta</Button></Panel><Panel title="Deskripsi laporan"><p className="body-copy">{t.description}</p></Panel><Panel title="Riwayat penanganan"><Timeline events={t.history}/></Panel></div><Panel title="Update Progress"><form onSubmit={e=>{e.preventDefault();if(!note.trim()){notify('Isi catatan tindakan terlebih dahulu');return}updateTicket(t.id,{status:selectedStatus,note:note.trim()});setNote('')}}><Field label="Status pekerjaan"><Select value={selectedStatus} onChange={setStatus} options={allowed}/></Field><Field label="Catatan tindakan"><textarea rows="5" value={note} onChange={e=>setNote(e.target.value)} placeholder="Apa yang sudah Anda kerjakan di lokasi?"/></Field><Field label="Foto progress (opsional)"><input type="file" accept="image/*"/></Field><Button type="submit" variant="full" disabled={t.archived}>Simpan update</Button></form></Panel></div></>;}
if(section==='tickets')return <><Header eyebrow="PEKERJAAN LAPANGAN" title="Ticket Saya" description="Daftar pekerjaan aktif dan tiket yang tersedia."/><Panel title="Ditugaskan kepada saya"><div className="tech-card-grid">{myTickets.map(t=><TechCard key={t.id} ticket={t}/>)}</div></Panel><Panel title="Belum ditugaskan"><div className="tech-card-grid">{unassigned.map(t=><TechCard key={t.id} ticket={t}/>)}</div></Panel></>;
if(section==='map')return <><Header eyebrow="LOKASI PEKERJAAN" title="Peta Layanan" description="Titik lokasi layanan untuk membantu kunjungan lapangan."/><div className="panel tech-map"><div className="map-canvas"><div className="map-road road-a"/><div className="map-road road-b"/><div className="map-road road-c"/><div className="map-label label-a">BANDUNG UTARA</div><div className="map-label label-b">BANDUNG TIMUR</div>{services.filter(s=>s.coord!=='—').map((s,i)=><Link key={s.id} to={'/technician/tickets/'+(tickets.find(t=>t.serviceId===s.id)?.id||1)} className={'map-marker marker-'+i}><MapPin size={27} fill="currentColor"/></Link>)}</div></div><Panel title="Lokasi pekerjaan"><div className="tech-card-grid">{myTickets.map(t=><TechCard key={t.id} ticket={t}/>)}</div></Panel></>;
if(section==='profile')return <TechnicianProfile/>;if(section==='vouchers')return <VoucherPage role="technician" vouchers={vouchers} changeVoucher={changeVoucher} notify={notify}/>;return <Empty title="Halaman tidak ditemukan"/>}
function TechCard({ticket}){return <div className="tech-task"><div className="tech-task-top"><Badge>{ticket.priority}</Badge><span>#{ticket.number}</span></div><h3>{ticket.title}</h3><p>{ticket.customer}</p><div className="tech-location"><MapPin size={15}/>{serviceOf(ticket).address}</div><div className="tech-task-bottom"><Badge>{ticket.status}</Badge><Link className="text-link" to={'/technician/tickets/'+ticket.id}>Lihat tiket <ArrowRight size={15}/></Link></div></div>}

createRoot(document.getElementById('root')).render(<App/>);
